#!/bin/sh
# Generate generated/routes.go from routes.txt.
set -eu
cd "$(dirname "$0")"
mkdir -p generated
{
	printf '%s\n' \
		'// Code generated by gen.sh from routes.txt. DO NOT EDIT.' \
		'' \
		'// Package generated holds values gen.sh writes from routes.txt.' \
		'package generated' \
		'' \
		'// Routes lists the registered routes.' \
		'var Routes = []string{'
	while read -r route; do
		if [ -n "$route" ]; then
			printf '\t"%s",\n' "$route"
		fi
	done <routes.txt
	printf '}\n'
} >generated/routes.go
